    import sys
    from collections import deque

    data = input_str.strip().split('\n')
    n, m = map(int, data[0].split())
    s, t = map(int, data[1].split())

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(m):
        u, v, w = map(int, data[2 + i].split())
        edges.append((u, v, w, i + 1))  # 1-indexed road ID
        adj[u].append((v, i))
        adj[v].append((u, i))

    def check_connectivity(removed_edges):
        """BFS to check if t is reachable from s avoiding removed_edges"""
        visited = [False] * (n + 1)
        visited[s] = True
        queue = deque([s])

        while queue:
            u = queue.popleft()
            if u == t:
                return True

            for v, edge_id in adj[u]:
                if not visited[v] and edge_id not in removed_edges:
                    visited[v] = True
                    queue.append(v)

        return False

    # Check 0 roads removed
    if not check_connectivity(set()):
        return "0\n0\n"

    # Check 1 road removed
    min_budget = float('inf')
    best_result = None

    for edge in edges:
        u, v, w, rid = edge
        removed = {rid}
        if not check_connectivity(removed):
            if w < min_budget:
                min_budget = w
                best_result = (min_budget, 1, [rid])

    if best_result:
        return f"{best_result[0]}\n{best_result[1]}\n{' '.join(map(str, best_result[2]))}\n"

    # Check 2 roads removed
    for edge1 in edges:
        u1, v1, w1, rid1 = edge1
        removed1 = {rid1}
        if check_connectivity(removed1):
            # Try removing 1 additional road
            for edge2 in edges:
                u2, v2, w2, rid2 = edge2
                if rid2 != rid1:
                    if not check_connectivity(removed1 | {rid2}):
                        total = w1 + w2
                        if total < min_budget:
                            min_budget = total
                            best_result = (total, 2, [rid1, rid2])

    if best_result:
        return f"{best_result[0]}\n{best_result[1]}\n{' '.join(map(str, best_result[2]))}"

    return "-1"

