from collections import defaultdict, deque
import sys
import os

def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')

    # First line: n and m
    if not lines:
        return "0\n"

    n, m = map(int, lines[0].split())

    # Build adjacency list for graph
    adj = defaultdict(list)
    for i in range(1, m + 1):
        if i <= len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)

    # Next line: parities (might need to handle differently)
    parities = []
    if m + 1 < len(lines):
        parities = list(map(int, lines[m + 1].split()))
    else:
        # Should not happen normally but handle edge case
        return "0\n"

    # Count odd parities
    odd_vertices = []
    for i in range(n):
        if i < len(parities) and parities[i] == 1:
            odd_vertices.append(i + 1)

    # In a single path, endpoints have odd degree, others have even
    # So we need 0 or 2 vertices with odd parity requirement
    if len(odd_vertices) > 2:
        return "-1\n"

    # Case: No odd parity vertices
    if len(odd_vertices) == 0:
        # Empty path satisfies all (0 visits = even for all)
        return "0\n"

    # Case: Exactly 2 odd parity vertices
    if len(odd_vertices) == 2:
        u, v = odd_vertices

        # BFS to find path between u and v
        visited = {u}
        parent = {u: None}
        queue = deque([u])

        v_found = False
        while queue and not v_found:
            curr = queue.popleft()
            if curr == v:
                v_found = True
                break
            for neighbor in adj[curr]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    parent[neighbor] = curr
                    queue.append(neighbor)

        if not v_found:
            # No path between u and v
            return "-1\n"

        # Reconstruct path from u to v
        path = []
        curr = v
        while curr is not None:
            path.append(curr)
            curr = parent[curr]

        # path is now v to u, reverse it to get u to v
        path = path[::-1]

        return f"{len(path)}\n" + " ".join(map(str, path))

    # Case: 1 odd parity vertex - impossible in single path
    if len(odd_vertices) == 1:
        return "-1\n"

    return "-1\n"


