def is_bitonic(arr):
    if len(arr) <= 2:
        return True

    # Check if there exists a peak position p such that arr is increasing up to p
    # and decreasing after p
    for peak in range(1, len(arr) - 1):
        increasing = all(arr[i] < arr[i + 1] for i in range(peak))
        decreasing = all(arr[i] > arr[i + 1] for i in range(peak, len(arr) - 1))
        if increasing and decreasing:
            return True
    return False


