from fractions import Fraction

def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    operations = []
    for i in range(n):
        t, x_prime, y = map(int, lines[i + 1].split())
        x = Fraction(x_prime, 100000)
        operations.append((t, x, y))

    # earliest[j] stores when banana count j is first reachable (-1 means unreachable)
    earliest = [-1] * m
    reachable = {0}

    for step, (t, x, y) in enumerate(operations, 1):
        new_counts = set()

        for k in list(reachable):
            current = k
            for _ in range(y):
                if current > m:
                    break

                if t == 1:
                    # Type 1: k := ceil(current + x)
                    current = int(math.ceil(current + x))
                else:
                    # Type 2: k := ceil(current * x)
                    current = int(math.ceil(current * x))

                if current <= m:
                    if current not in reachable and current not in new_counts:
                        new_counts.add(current)
                    if current == 0:
                        continue

        reachable.update(new_counts)
        for count in new_counts:
            if earliest[count] == -1:
                earliest[count] = step

    result_str = ' '.join(map(str, earliest))
    return f'\n{result_str} \n'

