def dist(p1, p2):
    return sqrt((p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2)

def sphere_from_2(p1, p2):
    center = ((p1[0] + p2[0]) / 2.0,
              (p1[1] + p2[1]) / 2.0,
              (p1[2] + p2[2]) / 2.0)
    radius = dist(p1, center)
    return center, radius

def sphere_from_3(p1, p2, p3):
    # Circumcenter of triangle in 3D
    d1 = dist(p1, p2)
    d2 = dist(p1, p3)
    d3 = dist(p2, p3)
    max_d = max(d1, d2, d3)

    if max_d == d1:
        return ((p1[0] + p2[0]) / 2.0, (p1[1] + p2[1]) / 2.0, (p1[2] + p2[2]) / 2.0), d1 / 2.0
    elif max_d == d2:
        return ((p1[0] + p3[0]) / 2.0, (p1[1] + p3[1]) / 2.0, (p1[2] + p3[2]) / 2.0), d2 / 2.0
    else:
        return ((p2[0] + p3[0]) / 2.0, (p2[1] + p3[1]) / 2.0, (p2[2] + p3[2]) / 2.0), d3 / 2.0

def solve_circumsphere(p1, p2, p3, p4):
    # Solve 3x3 linear system for 4-point circumsphere
    A = []
    b = []
    tol = 1e-10

    for i in range(1, 4):
        row = [2 * (p1[j] - p[i][j]) for j in range(3)]
        val = sum(p1[j]**2 for j in range(3)) - sum(p[i][j]**2 for j in range(3))
        A.append(row)
        b.append(val)

    pivot = [0, 1, 2]
    for i in range(3):
        max_idx = i
        for j in range(i, 3):
            if abs(A[j][pivot[i]]) > abs(A[max_idx][pivot[i]]):
                max_idx = j
        A[i], A[max_idx] = A[max_idx], A[i]
        b[i], b[max_idx] = b[max_idx], b[i]

        if abs(A[i][i]) < tol:
            return None

        for k in range(i + 1, 3):
            factor = A[k][i] / A[i][i]
            for j in range(i, 4):
                A[k][j] -= factor * A[i][j]
            b[k] -= factor * b[i]

    x = [0.0, 0.0, 0.0]
    for i in range(2, -1, -1):
        x[i] = b[i]
        for j in range(i + 1, 3):
            x[i] -= A[i][j] * x[j]
        x[i] /= A[i][i]

    return x

def minenclosingball(a, R, eps=1e-9):
    if len(a) == 0:
        if len(R) == 0:
            return None
        if len(R) == 1:
            return R[0], 0
        if len(R) == 2:
            return sphere_from_2(R[0], R[1])
        if len(R) == 3:
            return sphere_from_3(R[0], R[1], R[2])
        return None

    p = a.pop()
    c, r = minenclosingball(a, R + [p])
    a.append(p)

    if c is None or dist(p, c) <= r + eps:
        return c, r

    if minenclosingball(a, [p])[0] is None:
        c2, r2 = minenclosingball(a, [p])
        if c2 is None:
            c2, r2 = minenclosingball(a, [p])
        if c2 is not None and dist(p, c2) <= r2 + eps:
            return c2, r2
        return sphere_from_2(p, c2)
    return minenclosingball(a, [p])

