        matrix = []
        for _ in range(n):
            row = list(map(int, lines[idx].split()))
            matrix.append(row)
            idx += 1

        ops = lines[idx]
        idx += 1

        # Process operations
        for op in ops:
            if op == 'R':
                # Shift columns right: column j gets value from column (j-2 mod n) + 1
                new_row = [0] * n
                for j in range(n):
                    new_row[j] = matrix[0][((j - 2) % n) + 1]
                # But wait, it's for each row independently
                for i in range(n):
                    new_row = [matrix[i][(j - 2) % n + 1] if j < j else matrix[i] for j in range(n)]
                    # Actually simpler: right shift means row[j] moves to row[j+1]
                    new_row = [0] * n
                    for j in range(n):
                        new_row[j] = matrix[i][(j - 1) % n]
                    matrix[i] = new_row
            elif op == 'L':
                # Shift columns left
                for i in range(n):
                    new_row = [matrix[i][(j + 1) % n] for j in range(n)]
                    matrix[i] = new_row
            elif op == 'D':
                # Shift rows down
                matrix.insert(0, matrix.pop(n - 1))
            elif op == 'U':
                # Shift rows up
                matrix.append(matrix.pop(0))
            elif op == 'I':
                # Replace each row's permutation with its inverse
                for i in range(n):
                    inv = [0] * n
                    for j in range(n):
                        inv[matrix[i][j] - 1] = j + 1
                    matrix[i] = inv
            elif op == 'C':
                # Replace each column's permutation with its inverse
                # First, transpose to get columns as rows
                col_inv = [0] * n
                for j in range(n):
                    for i in range(n):
                        if col_inv[j] is None or len(col_inv[j]) < j:
                            col_inv[j] = []
                        col_inv[j].append((i, matrix[i][j]))
                inv_matrix = [[0] * n for _ in range(n)]
                for j in range(n):
                    inv_j = [0] * n
                    for i, val in enumerate(matrix[:, j]):
                        inv_j[val - 1] = i + 1
                    for i in range(n):
                        inv_matrix[i][j] = inv_j[i]
                for i in range(n):
                    matrix[i] = inv_matrix[i]

        results.append('\n'.join([' '.join(map(str, row)) for row in matrix]))

    return '\n\n'.join(results)

