    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    p = n + 1

    if not is_prime(p):
        return '-1\n'

    def mod_exp(base, exp, mod):
        result = 1
        base %= mod
        while exp > 0:
            if exp & 1:
                result = (result * base) % mod
            exp >>= 1
            base = (base * base) % mod
        return result

    # Get prime factors of p-1 = n
    def get_prime_factors(num):
        factors = []
        d = 2
        temp = num
        while d * d <= temp:
            while temp % d == 0:
                factors.append(d)
                temp //= d
            d += 1
        if temp > 1:
            factors.append(temp)
        return factors

    pf = get_prime_factors(p - 1)

    # Check bases from x-1 down to 2
