        # For b >= p, we only care if mod_exp(b, p-1, p) == 1
        # For b < p, by Fermat's little theorem, this is always true

        # Check if b is a primitive root mod p
        # b is primitive root if b^((p-1)/q) != 1 (mod p) for all prime factors q of p-1
        is_primitive_root = True
        for q in pf:
