# Solution for the "Little X" problem
# This is a constraint satisfaction problem involving pairing numbers based on modular arithmetic-like rules

def build_constraint_graph(n: int, a: int, b: int, p: List[int], p_set: Dict[int, int], p_positions: List[int]) -> List[List[int]]:
    """
    Build a graph where nodes represent numbers and edges represent constraints.
    Uses a coloring approach where we try to assign each number to set A (0) or B (1).
    """
    # Create graph with constraint edges
    # For each number, we track what other number it must pair with
    graph = [[] for _ in range(n)]

    # A number can only be in A if a-x is also in the input (or a-x==x in one element set)
    # A number can only be in B if b-x is also in the input (or b-x==x in one element set)

    # Build the graph of "must be in the same set" relationships
    for i in range(n):
        x = p[i]

        # Check if we can pair x with (a-x) in set A
        if (a - x) in p_set:
            j = p_set[a - x]
            if i == j:
                # Self-pair, no additional constraint beyond being in A
                graph[i].append(0)  # Same set
            else:
                # Must be in same set if both require A
                graph[i].append(j)

        # Check if we can pair x with (b-x) in set B
        if (b - x) in p_set:
            j = p_set[b - x]
            if i == j:
                # Self-pair in B
                graph[i].append(0)
            else:
                graph[i].append(j)

    # Adjust edges for the "same set" constraint graph
    graph = [[0] for _ in range(n)]  # Initialize with home relation

    for i in range(n):
        x = p[i]
        # For A constraint: if a-x exists, must be same set or compatible
        if (a - x) in p_set and p_set[a - x] != i:
            graph[i].append(p_set[a - x])

        # For B constraint: if b-x exists, must be same set or compatible
        if (b - x) in p_set and p_set[b - x] != i:
            graph[i].append(p_set[b - x])

    return graph

def try_satisfy_assignment(n: int, a: int, b: int, p: List[int], p_set: Dict[int, int], assignments: List[int]):
    """
    Try to satisfy the assignment using 2-SAT approach.
    returns True if valid, False otherwise
    """
    # Build implication graph for 2-SAT
    # Each variable i has two states: assigned to A (0) or B (1)
    # If we assign x to A, must check if a-x can also be in A
    # If we assign x to B, must check if b-x can also be B

    for i in range(n):
        x = p[i]
        choice = assignments[i]

        if choice == 0:  # Assigned to A
            if (a - x) in p_set:
                j = p_set[a - x]
                if assignments[j] != 0:
                    # j is not in A, but x needs a-x in A
                    return False
        elif choice == 1:  # Assigned to B
            if (b - x) in p_set:
                j = p_set[b - x]
                if assignments[j] != 1:
                    # j is not in B, but x needs b-x in B
                    return False

    return True

