import math

def solution(input_str):
    MOD = 1051131

    lines = input_str.strip().split('\n')
    first = lines[0].split()
    m, t, s = int(first[0]), int(first[1]), int(first[2])

    a = list(map(int, lines[1].split()))
    n = 2 * m

    # Generate the rest of array a
    for i in range(s, n):
        ai = (101 * a[-1] + 10007) % MOD
        a.append(ai)

    def mat_mul(A, B):
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k] == 0:
                    continue
                for j in range(n):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A, p):
        if p == 0:
            result = [[0] * n for _ in range(n)]
            for i in range(n):
                result[i][i] = 1
            return result
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1
        base = [row[:] for row in A]
        while p > 0:
            if p & 1:
                    result = mat_mul(result, base)
            base = mat_mul(base, base)
            p >>= 1
        return result

    # Number of divisors of k
    def num_divisors(k):
        if k == 0:
            return 0
        count = 0
        for d in range(1, int(k**0.5) + 1):
            if k % d == 0:
                count += 1
                if d * d != k:
                    count += 1
        return count

    # Build adjacency matrix for island transitions
    size = n
    Adj = [[0] * size for _ in range(size)]
    for i in range(n):
        for j in range(n):
            if i == j:
                # Stay option: 1 way (always can rest)
                Adj[i][j] = 1
            else:
                # Number of bridges between islands i+1 and j+1
                # 2k = 2^(number of divisors of gcd(i+1, j+1))
                common_divisors = num_divisors(math.gcd(i + 1, j + 1))
                adjacency = pow(2, common_divisors, MOD)
                Adj[i][j] = adjacency

    # Compute Adj^t
    Adjt = mat_pow(Adj, t)

    # Calculate ans[i] for each island i
    ans = []
    for j in range(n):
        total = 0
        for i in range(n):
            total = (total + a[i] * Adjt[i][j]) % MOD
        ans.append(total)

    # XOR sum
    xor_sum = 0
    for x in ans:
        xor_sum ^= x

    return str(xor_sum) + '\n'

