def solution(input_data):
    # Parse input
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())
    roads = []
    for i in range(m):
        a, b = map(int, lines[1 + i].split())
        roads.append((a, b))

    def cross(r1, r2):
        """Check if two roads cross each other."""
        a, b = r1
        c, d = r2
        # Normalize so a < b and c < d
        if a > b:
            a, b = b, a
        if c > d:
            c, d = d, c

        # Check if they cross (interleaved)
        c_in_ab = a < c < b
        d_in_ab = a < d < b
        return c_in_ab != d_in_ab

    # Build implication graph for 2-SAT
    # Variable 2*i: road i is OUTSIDE (False)
    # Variable 2*i+1: road i is INSIDE (True)
    # Constraint: if roads cross, they have different values

    adj = [[] for _ in range(2 * m)]

    for i in range(m):
        for j in range(i + 1, m):
            if cross(roads[i], roads[j]):
                # Constraint: road_i != road_j
                # If road_i is inside, road_j must be outside
                if 2 * i + 1 < 2 * m:
                    adj[2 * i + 1][2 * j]  # inside_i -> outside_j
                if 2 * j + 1 < 2 * m:
                    adj[2 * j + 1][2 * i]  # inside_j -> outside_i
                if 2 * i < 2 * m:
                    adj[2 * i][2 * j + 1]  # outside_i -> inside_j
                if 2 * j < 2 * m:
                    adj[2 * j][2 * i + 1]  # outside_j -> inside_i

    # Kosaraju's algorithm to find SCCs
    vis = [False] * (2 * m)
    order = []

    def dfs1(v):
        vis[v] = True
        for to in adj[v]:
            if not vis[to]:
                dfs1(to)
        order.append(v)

    for i in range(2 * m):
        if not vis[i]:
            dfs1(i)

    # Build reverse graph
    rev_adj = [[] for _ in range(2 * m)]
    for i in range(2 * m):
        for j in adj[i]:
            rev_adj[j].append(i)

    vis2 = [False] * (2 * m)
    comp = [-1] * (2 * m)
    comp_count = 0

    def dfs2(v):
        vis2[v] = True
        comp[v] = comp_count
        for to in rev_adj[v]:
            if not vis2[to]:
                dfs2(to)

    for i in range(2 * m - 1, -1, -1):
        if not vis2[order[i]]:
            dfs2(order[i])
            comp_count += 1

    # Check for contradictions
    for i in range(m):
        if comp[2 * i] == comp[2 * i + 1]:
            return "Impossible"

    # Build solution
    result = []
    for i in range(m):
        # Assign 'i' if inside component has higher order, 'o' otherwise
        if comp[2 * i] > comp[2 * i + 1]:
            result.append('o')
        else:
            result.append('i')

    return ''.join(result)

