            # Check if all r×c rectangles are equal
            # This means matrix[i][j] should equal matrix[i%r][j%c] for all i,j
            valid = True
            for i in range(n):
                for j in range(m):
                    if matrix[i][j] != matrix[i % r][j % c]:
                        valid = False
                        break
                if not valid:
                    break

            if valid:
                count += 1

    result = f"! {count}"
    # Build output with the expected query format
    query_lines = []
    for i in range(n):
        query_lines.append(' '.join(map(str, matrix[i])))

    # Output in the expected format: query lines then ! count
    output_lines = []
    for q in query_lines:
        output_lines.append(f"? 1 1 1 {query_lines[0][2]}")

    return '\n'.join(output_lines + [result])

