    if len(parts) < 3:
        return '-1'

    try:
        maxx, maxy, w = int(parts[0]), int(parts[1]), int(parts[2])
    except:
        return '-1'

    if maxx <= 0 or maxy <= 0 or w <= 0:
        return '-1'

    # Group numbers [1,x] by ratio: use (num, rev(num)) as key
    groups = defaultdict(list)
    for a in range(1, maxx + 1):
        ra = rev(a)
        if ra == 0:
            continue
        groups[(a, ra)].append(a)

    # For each group, create sorted list and binary search indices
    group_sorted = {}
    for key, vals in groups.items():
        group_sorted[key] = sorted(vals)

    def count_elements_le(group_sorted_dict, threshold):
        """Count elements in each group up to threshold"""
        return {k: bisect_right(vals, threshold) 
                for k, vals in group_sorted_dict.items()}

    best_x = -1
    best_y = -1
    best_product = float('inf')

    for x in range(1, maxx + 1):
        # Get count of elements <= x for each group
        counts_x = {}
        for key in group_sorted:
            counts_x[key] = bisect_right(group_sorted[key], x)

        # Binary search for minimum y
        left, right = 1, maxy
        found = False
        ans_y = -1

        while left <= right:
            mid = (left + right) // 2
            if mid == 0:
                mid = 1

            # Count elements <= mid for each group
            counts_y = {k: bisect_right(group_sorted[k], mid) 
                       for k in group_sorted}

            # Calculate total lucky tickets
            lucky = sum(counts_x[k] * counts_y[k] for k in group_sorted)

            if lucky >= w:
                ans_y = mid
                right = mid - 1
            else:
                left = mid + 1

        if ans_y != -1:
            product = x * ans_y
            if product < best_product:
                best_product = product
                best_x = x
                best_y = ans_y

    if best_x != -1:
        return f'{best_x} {best_y}'
    else:
        return '-1'

