def solution(input_str):
    n, k, m = map(int, input_str.split())
    MOD = 10**9 + 7

    if k == 1:
        return str(n)

    from functools import lru_cache

    @lru_cache(None)
    def dp(current, visited_mask, steps):
        """
        current: current planet (1-indexed)
        visited_mask: bitmask of visited planets
        steps: number of remaining moves needed
        """
        if steps == 0:
            return 1

        count = 0
        max_reach = min(n, current + m)

        for next_planet in range(1, max_reach + 1):
            # Check if next_planet hasn't been visited
            if not (visited_mask & (1 << (next_planet - 1))):
                count = (count + dp(next_planet, visited_mask | (1 << (next_planet - 1)), steps - 1)) % MOD

        return count

    total = 0
    for start in range(1, n + 1):
        total = (total + dp(start, 1 << (start - 1), k - 1)) % MOD

    return str(total)

