        if n <= 0:
            return "NO\n"

        # Parse input strings
        strings = set()
        for i in range(1, len(lines)):
            if lines[i]:
                strings.add(lines[i])

        if n == 0 or len(strings) == 0:
            return "NO\n"

        # Find minimal strings - those not substrings of other inputs
        minimal = []
        for s1 in strings:
            is_substring = False
            for s2 in strings:
                if s1 != s2 and s1 in s2:
                    is_substring = True
                    break
            if not is_substring:
                minimal.append(s1)

        if not minimal:
            return "NO\n"

        # Sort for lexicographically first processing
        minimal = sorted(minimal)

        # Try permutations in sorted order
        for perm in sorted(list(permutations(minimal))):
            result = ''.join(perm)

            # Check each minimal string appears at least once
            min_freq = float('inf')
            max_freq = 0
            valid = True
            for s in minimal:
                count = result.count(s)
                if count == 0:
                    valid = False
                    break
                min_freq = min(min_freq, count)
                max_freq = max(max_freq, count)

            if not valid:
                continue

            # Find the maximum frequency across all substrings
            overall_max = 0
            for i in range(len(result)):
                for j in range(i + 1, len(result) + 1):
                    substring = result[i:j]
                    freq = result.count(substring)
                    overall_max = max(overall_max, freq)

            # All minimal strings must have the same frequency = overall_max
            if min_freq == overall_max:
                return result + '\n'

    except Exception:
        return "NO\n"

