import math
from functools import lru_cache

def get_square_free(x):
    """Compute the square-free part of x by removing all square factors."""
    res = 1
    temp = x
    d = 2
    while d * d <= temp:
        count = 0
        while temp % d == 0:
            count += 1
            temp //= d
        if count % 2 == 1:
            res *= d
        d += 1
    if temp > 1:
        res *= temp
    return res

def solution(input_text):
    lines = input_text.strip().split('\n')
    if not lines:
        return '0'

    try:
        n = int(lines[0])
    except:
        return '0'

    if n == 0:
        return '0'

    if n == 1:
        if len(lines) > 1 and lines[1].strip():
            return '1'
        return '0'

    # Collect all integers after first line, handling multiline input
    remaining = ' '.join(lines[1:]) if len(lines) > 1 else ''
    a = list(map(int, remaining.split()))

    if len(a) != n:
        return '0'

    MOD = 10**9 + 7

    # Group numbers by their square-free part
    sf_map = {}
    for val in a:
        sf = get_square_free(val)
        if sf not in sf_map:
            sf_map[sf] = []
        sf_map[sf].append(val)

    # Groups sizes
    counts = [len(v) for v in sf_map.values()]
    m = len(counts)

    # If only one group and more than 1 element, no valid permutation (all adjacent pairs bad)
    if m == 1 and len(a) > 1:
        return '0'

    @lru_cache(maxsize=None)
    def dp(rem, last_g):
        """
        DP to count valid sequences.
        rem: tuple of remaining counts from each group
        last_g: index of last used group (-1 for start)
        """
        if sum(rem) == 0:
            return 1
        ans = 0
        for i in range(m):
            if rem[i] > 0 and i != last_g:
                new_rem = list(rem)
                new_rem[i] -= 1
                ans = (ans + dp(tuple(new_rem), i)) % MOD
        return ans

    # Compute number of valid arrangements with group labels
    result = dp(tuple(counts), -1)

    # Multiply by factorials to account for actual element arrangements within each group
    for c in counts:
        result = (result * math.factorial(c)) % MOD

    return str(result)
